def transform(grid):
    n = len(grid)
    m = len(grid[0])
    out = [row[:] for row in grid]
    for r in range(n):
        for c in range(m):
            if grid[r][c] != 2:
                continue
            orbit = {
                (r, c), (n - 1 - r, c), (r, m - 1 - c),
                (n - 1 - r, m - 1 - c), (c, r), (m - 1 - c, r),
                (c, n - 1 - r), (m - 1 - c, n - 1 - r)
            }
            vals = [grid[i][j] for i, j in orbit
                    if 0 <= i < n and 0 <= j < m and grid[i][j] != 2]
            if vals:
                out[r][c] = vals[0]
    return out
